<?php $step=$step??1; $error=$error??''; $labels=[1=>'欢迎',2=>'数据库',3=>'迁移',4=>'管理员',5=>'完成']; ?>
<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ClayUP 安装向导</title><style>
:root{--bg:#f8fafc;--card:#fff;--text:#0f172a;--muted:#64748b;--line:#e2e8f0;--primary:#2563eb;--primary2:#06b6d4;--danger:#dc2626;--ok:#16a34a}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at 15% 0%,rgba(37,99,235,.14),transparent 28%),linear-gradient(180deg,#f8fafc,#eef2f7);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:var(--text);padding:24px}.card{width:100%;max-width:620px;background:#fff;border-radius:18px;box-shadow:0 16px 50px rgba(15,23,42,.10);overflow:hidden}.head{padding:30px 34px;background:linear-gradient(135deg,var(--primary),var(--primary2));color:white}.head h1{margin:0 0 6px;font-size:24px}.head p{margin:0;opacity:.85}.steps{display:flex;gap:6px;padding:18px 28px;border-bottom:1px solid var(--line)}.step{flex:1;text-align:center;color:var(--muted);font-size:12px}.dot{width:28px;height:28px;margin:0 auto 5px;border-radius:50%;display:grid;place-items:center;background:#e2e8f0;font-weight:700}.active .dot,.done .dot{background:var(--primary);color:white}.active,.done{color:var(--primary);font-weight:700}.body{padding:28px 34px}.err{background:#fee2e2;color:#991b1b;padding:12px 14px;border-radius:10px;margin-bottom:16px}.note{background:#eff6ff;color:#1d4ed8;padding:13px 15px;border-radius:12px;margin:12px 0;line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.full{grid-column:1/-1}label{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}.input{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px 13px;font-size:14px}.btn{width:100%;border:0;background:var(--primary);color:white;border-radius:10px;padding:13px 18px;font-weight:700;cursor:pointer;text-decoration:none;text-align:center;display:block;margin-top:16px}.ok{text-align:center;font-size:56px;margin-bottom:12px}@media(max-width:640px){body{padding:12px}.grid{grid-template-columns:1fr}.head,.body{padding:22px}.steps{padding:14px;overflow-x:auto}.step{min-width:62px}}
</style></head><body><div class="card"><div class="head"><h1>ClayUP 安装向导</h1><p>官方更新站系统安装</p></div><div class="steps"><?php for($i=1;$i<=5;$i++): $cls=$i<$step?'done':($i===$step?'active':''); ?><div class="step <?= $cls ?>"><div class="dot"><?= $i<$step?'✓':$i ?></div><?= $labels[$i] ?></div><?php endfor; ?></div><div class="body"><?php if($error): ?><div class="err"><?= htmlspecialchars($error) ?></div><?php endif; ?>
<?php if($step===1): ?><h2>欢迎使用 ClayUP</h2><p style="color:var(--muted);line-height:1.8">安装向导将完成数据库创建、数据表导入、平台管理员创建。</p><div class="note">请准备 MySQL 管理账号。数据库不存在时会自动创建。</div><form method="post" action="/install.php"><?= csrf_field() ?><input type="hidden" name="step" value="2"><button class="btn">开始安装</button></form>
<?php elseif($step===2): ?><h2>数据库配置</h2><form method="post" action="/install.php" class="grid"><?= csrf_field() ?><input type="hidden" name="step" value="2"><div><label>地址</label><input class="input" name="db_host" value="localhost" required></div><div><label>端口</label><input class="input" name="db_port" value="3306" required></div><div><label>数据库</label><input class="input" name="db_name" value="gfgx_update" required></div><div><label>用户名</label><input class="input" name="db_user" value="root" required></div><div class="full"><label>密码</label><input class="input" name="db_pass" type="password"></div><button class="btn full">测试连接并保存配置</button></form>
<?php elseif($step===3): ?><h2>执行数据库迁移</h2><p style="color:var(--muted)">数据库连接成功，点击按钮导入系统表。</p><form method="post" action="/install.php"><?= csrf_field() ?><input type="hidden" name="step" value="3"><input type="hidden" name="run_migration" value="1"><button class="btn">执行迁移</button></form>
<?php elseif($step===4): ?><h2>创建平台管理员</h2><form method="post" action="/install.php" class="grid"><?= csrf_field() ?><input type="hidden" name="step" value="4"><div class="full"><label>邮箱</label><input class="input" name="admin_email" type="email" required></div><div><label>名称</label><input class="input" name="admin_name" value="admin" required></div><div><label>密码</label><input class="input" name="admin_pass" type="password" required></div><button class="btn full">创建管理员并完成安装</button></form>
<?php elseif($step===5): ?><div class="ok">🎉</div><h2 style="text-align:center">安装完成</h2><p style="text-align:center;color:var(--muted)">ClayUP 已准备就绪。</p><a class="btn" href="/index.php?path=login">去登录</a><?php endif; ?></div></div></body></html>